const page = atob("");

const schema = {
  name: "schedule_update",
  strict: true,
  schema: {
    type: "object", additionalProperties: false,
    properties: {
      type: { type: "string", enum: ["cancellation", "reschedule", "deadline", "new event", "info"] },
      course_code: { type: ["string", "null"], enum: ["ECO101", "STA102", "WRT103", "PHI104", "DAT201", null] },
      date_phrase: { type: ["string", "null"] },
      time_24h: { type: ["string", "null"] },
      room: { type: ["string", "null"] },
      title: { type: ["string", "null"] },
      evidence_quote: { type: "string" },
    },
    required: ["type", "course_code", "date_phrase", "time_24h", "room", "title", "evidence_quote"],
  },
};
const json = (value, status = 200) => new Response(JSON.stringify(value), { status, headers: { "content-type": "application/json; charset=utf-8", "cache-control": "no-store" } });

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (url.pathname === "/api/health") return json({ ok: true, llm: Boolean(env.OPENAI_API_KEY), model: env.OPENAI_MODEL || "gpt-4.1-mini" });
    if (url.pathname === "/api/extract" && request.method === "POST") {
      let body;
      try { body = await request.json(); } catch { return json({ error: "Invalid JSON." }, 400); }
      const text = String(body.text || "").trim();
      if (!text || text.length > 20000) return json({ error: "Provide an update up to 20,000 characters." }, 400);
      if (!env.OPENAI_API_KEY) return json({ error: "AI extraction is not configured." }, 503);
      const prompt = `Extract the single most actionable schedule change from this programme update. Return only the requested structured fields. Do not convert relative dates to calendar dates. Do not guess; use null. evidence_quote must be copied verbatim. Known course codes: ECO101 Economics, STA102 Statistics, WRT103 Writing & Rhetoric, PHI104 Ethics, DAT201 Data Lab. Message received at ${String(body.received || "unknown")} Asia/Kolkata.\n\n${text}`;
      try {
        const response = await fetch("https://api.openai.com/v1/chat/completions", {
          method: "POST",
          headers: { "authorization": `Bearer ${env.OPENAI_API_KEY}`, "content-type": "application/json" },
          body: JSON.stringify({ model: env.OPENAI_MODEL || "gpt-4.1-mini", temperature: 0, messages: [{ role: "system", content: "You extract grounded schedule changes from academic updates. Use only facts stated in the source." }, { role: "user", content: prompt }], response_format: { type: "json_schema", json_schema: schema } }),
        });
        if (!response.ok) return json({ error: "AI extraction is temporarily unavailable." }, 502);
        const result = await response.json();
        const raw = result.choices?.[0]?.message?.content;
        if (!raw) return json({ error: "No structured result was returned." }, 502);
        const parsed = JSON.parse(raw), norm = value => String(value || "").replace(/\s+/g, " ").trim().toLowerCase();
        if (!parsed.evidence_quote || !norm(text).includes(norm(parsed.evidence_quote))) return json({ error: "Evidence could not be verified against the source." }, 422);
        if (parsed.date_phrase && !norm(text).includes(norm(parsed.date_phrase))) parsed.date_phrase = null;
        if (parsed.time_24h && !/^(?:[01]\d|2[0-3]):[0-5]\d$/.test(parsed.time_24h)) parsed.time_24h = null;
        return json({ ...parsed, mode: "openai" });
      } catch { return json({ error: "AI extraction failed validation." }, 502); }
    }
    if (url.pathname !== "/") return new Response("Not found", { status: 404 });
    return new Response(page, { headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-store" } });
  },
};
